#[allow(clippy::too_many_arguments)]
pub fn ring_momentum(d: f64, s: f64, rho: f64, v: f64) -> f64 {
    let mut h: f64 = 0.0;
    let mut a: f64 = ((core::f64::consts::PI * rt::ipow(d, 2)) / 4.0);
    h = ((((2.0 * rho) * a) * v) * s);
    h
}

