/// Standard gravity (CGPM 1901, exact).
pub const G0: f64 = 9.80665;

/// The propellant of one slew by thrusters alone: impulse H/r to start and the same to stop,
/// m = (2 H/r)/(Isp g0).
/// - h: real[N m s] (passed in m^2 kg/s)
/// - r: real[m] (passed in m)
/// - isp: real[s] (passed in s)
/// - returns m_p: real[kg] (passed in kg)
#[allow(clippy::too_many_arguments)]
pub fn propellant_per_slew(h: f64, r: f64, isp: f64) -> f64 {
    let mut m_p: f64 = 0.0;
    m_p = (((2.0 * h) / r) / (isp * crate::act::G0));
    m_p
}

/// Days in a Julian year.
pub const DAYS_PER_YEAR: f64 = 365.25;

/// The propellant of a year of slews: m_p n_day 365.25 when thrusters are fitted, else 0.
/// - m_p: real[kg] (passed in kg)
/// - n_day: real[1] (passed a plain number)
/// - n_rcs: int (passed a whole number)
/// - returns m_year: real[kg] (passed in kg)
#[allow(clippy::too_many_arguments)]
pub fn propellant_per_year(m_p: f64, n_day: f64, n_rcs: i64) -> f64 {
    let mut m_year: f64 = 0.0;
    if (n_rcs > 0) {
        m_year = ((m_p * n_day) * crate::act::DAYS_PER_YEAR);
    } else {
        m_year = 0.0;
    }
    m_year
}

